test("F06: incomplete pagination never admits a seat wake; a complete listing does", async (t) => {
  for (const mode of ["missing", "repeated", "capped", "complete"] as const) {
    await t.test(mode, async (t) => {
      t.mock.timers.enable({ apis: ["setTimeout"] });
      const home = mkdtempSync(join(tmpdir(), "ar-f06-"));
      const previous = process.env.PASEO_HOME;
      process.env.PASEO_HOME = home;
      mkdirSync(join(home, "agents-remember"));
      writeFileSync(join(home, "agents-remember", "role-agents.json"), JSON.stringify({ agents: { seat: facts, parent } }));
      const handlers = new Map<string, (event: unknown, context: unknown) => void>();
      const server = { on(name: string, handler: (event: unknown, context: unknown) => void) {
        handlers.set(name, handler);
        return () => {};
      } } as unknown as Pick<PluginLifecycleRegistration, "on">;
      const sent: { id: string; text: string }[] = [];
      let reads = 0;
      const context = { paseo: { agents: {
        ref: (id: string) => ({ async send(text: string) { sent.push({ id, text }); } }),
        list: async () => {
          reads += 1;
          return {
            // Include both records: suppression must be caused by incompleteness,
            // not by the absent-seat guard or a missing parent record.
            entries: ["seat", "parent"].map((id) => ({ agent: { id, labels: {}, activeTurn: null, pendingPermissions: [] } })),
            pageInfo: { hasMore: mode !== "complete", nextCursor: mode === "missing" ? null : mode === "repeated" ? "same" : `page-${reads}` },
          };
        },
      } } };
      const cleanup = registerParentWakeEvents(server, { home });
      try {
        handlers.get("agent.turn_ended")!({ agent: { id: "seat", parentAgentId: "parent" }, timeline: [], outcome: { kind: "completed" }, turnId: null }, context);
        await settle();
        const readsAtEnd = reads;
        const seatBefore = sent.filter((message) => message.id === "seat").length;
        assert.equal(seatBefore, 0, "nothing wakes the seat before the wait");
        t.mock.timers.tick(60_000);
        await settle();
        const rows = readFileSync(join(home, "agents-remember", "turn-ends.jsonl"), "utf8").trim().split("\n").map((line) => JSON.parse(line) as { kind: string; reason: string; count: number });
        if (mode === "complete") {
          assert.equal(readsAtEnd, 1);
          assert.equal(reads, 2, "one complete read at end, one at delivery");
          assert.equal(sent.filter((message) => message.id === "seat").length, 1);
          assert.deepEqual(rows.map((row) => [row.kind, row.count]), [["seat-message", 1]]);
        } else {
          assert.equal(readsAtEnd, mode === "missing" ? 1 : mode === "repeated" ? 2 : 8);
          assert.equal(reads, readsAtEnd, "no wait or delivery read was admitted");
          assert.equal(sent.filter((message) => message.id === "seat").length, 0);
          assert.deepEqual(rows.map((row) => [row.kind, row.reason, row.count]), [["left-alone", "host-state-unavailable", 0]]);
          assert.equal(sent.filter((message) => message.id === "parent").length, 1, "MIK-R172's ordinary parent line is preserved");
        }
      } finally {
        cleanup();
        if (previous === undefined) delete process.env.PASEO_HOME;
        else process.env.PASEO_HOME = previous;
        rmSync(home, { recursive: true, force: true });
      }
    });
  }
});

let cached: { path: string; generation: string; facts: Record<string, TurnEndedFacts> } | undefined;

export function readRoleAgents(home: string | undefined): Record<string, TurnEndedFacts> {
  if (home === undefined || home === "") return {};
  const path = roleAgentsPath(home);
  let text: string;
  let generation: string;
  try {
    const stat = statSync(path, { bigint: true });
    generation = [stat.dev, stat.ino, stat.size, stat.mtimeNs, stat.ctimeNs].join(":");
    if (cached?.path === path && cached.generation === generation) return cached.facts;
    text = readFileSync(path, "utf8");
  } catch (error) {
    cached = undefined;
    if ((error as { code?: string }).code === "ENOENT") return {};
    throw error;
  }
  const document: unknown = JSON.parse(text);
  if (typeof document !== "object" || document === null) {
    throw new Error(`malformed role-agents file at ${roleAgentsPath(home)}`);
  }
  const agents = (document as { agents?: unknown }).agents;
  if (typeof agents !== "object" || agents === null || Array.isArray(agents)) {
    throw new Error(`malformed role-agents file at ${roleAgentsPath(home)}`);
  }
  const facts: Record<string, TurnEndedFacts> = {};
  for (const [agentId, record] of Object.entries(agents)) {
    if (!isFacts(record)) {
      throw new Error(`malformed role-agents file at ${roleAgentsPath(home)}`);
    }
    facts[agentId] = { role: record.role, task: record.task, reportPath: record.reportPath };
  }
  cached = { path, generation, facts };
  return facts;
}

async function deliverSeatWake(
  wait: PendingSeatWake,
  tracker: TurnEndedTracker,
  now: () => Date,
  readHost: HostStateReader | undefined,
): Promise<void> {
  if (tracker.waits.get(wait.seat) !== wait) return;
  tracker.waits.delete(wait.seat);
  const states = await readHostStates(readHost);
  // Rule 4: a turn start or a shutdown between the timer and this act voids it.
  if (tracker.epoch !== wait.epoch || (tracker.seatEpoch.get(wait.seat) ?? 0) !== wait.seatEpoch) return;
  const skipped = hostFactsUnavailable(readHost, states, wait.seat)
    ? "host-state-unavailable"
    : archivedNow(wait.seat, states, tracker)
      ? "archived"
      : permissionNow(wait.seat, states, tracker)
        ? "permission-wait"
        : inTurnNow(wait.seat, states, tracker)
          ? "in-a-turn"
          : null;
  if (skipped !== null) {
    tracker.append(turnEndRow("send-skipped", wait.facts, wait.seat, wait.ordinal, skipped, isoWithOffset(now())));
    return;
  }
  try {
    await wait.deliver();
  } catch (error) {
    // The act writes its own row where it knows more; this is the last resort, and
    // the end is not counted because nothing reached anyone.
    tracker.append(
      turnEndRow(
        "delivery-failed",
        wait.facts,
        wait.seat,
        wait.ordinal,
        error instanceof Error ? error.message : String(error),
        isoWithOffset(now()),
      ),
    );
  }
}

export function recogniseArTool(item: Record<string, unknown>): string | null {
  if (item["type"] !== "tool_call") return null;
  const kind = acpKindOf(item);
  if (kind !== null && NON_AR_KINDS.has(kind)) return null;
  for (const text of identityTexts(item)) {
    const identity = normalisedWords(identityOf(text));
    if (identity === "") continue;
    const namesServer = AR_SERVER_WORDS.some((server) => identity.includes(server));
    for (const [tool, words] of AR_TOOL_WORDS) {
      if (identity === words || identity === tool) return tool;
      if (namesServer && identity.includes(words)) return tool;
    }
  }
  return null;
}

export function composeSeatWakeMessage(
  agentId: string,
  facts: TurnEndedFacts,
  lastText: TurnLastText,
  helperDispatched = false,
): string {
  const said =
    lastText.kind === "text" ? lastText.text : lastText.kind === "empty" ? "no text" : "unreadable";
  const message =
    `${SEAT_WAKE_FIRST_LINE} ${facts.role} ${agentId} · ${facts.task}\n` +
    `you last said: ${said}\n` +
    "Go on with your stage in this turn, or send what blocks you to your parent with role_message." +
    (helperDispatched
      ? " On this host a helper's result does not come back as a message: collect what your helpers finished and go on."
      : "");
  return message.length <= TURN_ENDED_LINE_LIMIT ? message : message.slice(0, TURN_ENDED_LINE_LIMIT);
}

