            outcome: event.outcome?.kind,
            // Rule 3/4: the host's own state at this end and at the send.
            readHost: () => readHostState(context.paseo as unknown as { agents: { list: (args: unknown) => Promise<unknown> } }),
          },
        );
        // MIK-R172 rule 5: an agent the agent list does not hold is named in
        // the host log once, with the reason, instead of being skipped silently.
        if (outcome.kind === "none" && outcome.log !== undefined) console.warn(outcome.log);
      } catch (error) {
        console.error("agents-remember turn_ended handler failed", error);
      }
    })();
  });

  server.on("agent.permission_requested", (event) => {
    notePermissionRequested(event.agent.id, turns);
  });

  server.on("agent.permission_resolved", (event, context) => {
    void (async () => {
      try {
        await notePermissionResolved(
          event.agent.id,
          turns,
          { sendMessage: (id, text) => context.paseo.agents.ref(id).send(text, { activeTurnBehavior: "steer" }) },
          // A line held for a departed parent is re-resolved at this send.
          readRoleAgents(process.env.PASEO_HOME),
        );
      } catch (error) {
        console.error("agents-remember permission_resolved handler failed", error);
      }
    })();
  });

  server.on("agent.archived", (event) => {
    noteAgentArchived(event.agent.id, turns);
  });

  // Rule 8: the plugin's cleanup clears every pending wait, so a reload starts
  // afresh and no wait fires after it.
  return () => cleanupSeatWaits(turns);
}

export function createTurnEndLog(home: string | undefined, options: TurnEndLogOptions = {}): TurnEndLog {
  const path = home === undefined || home === "" ? null : turnEndLogPath(home);
  const errorPath = home === undefined || home === "" ? null : turnEndErrorPath(home);
  const limit = options.limitBytes ?? TURN_END_LOG_LIMIT_BYTES;
  const now = options.now ?? (() => new Date());
  let failed = false;
  return {
    append(row) {
      if (path === null || errorPath === null) return;
      const line = `${JSON.stringify(row)}\n`;
      try {
        mkdirSync(dirname(path), { recursive: true });
        turnOverIfFull(path, Buffer.byteLength(line, "utf8"), limit);
        appendFileSync(path, line, "utf8");
      } catch (error) {
        // Rule 7: the failure is named in its own file, once, and the rule goes
        // on. `host-activity.json` is not touched — its readers forbid extra keys.
        if (failed) return;
        failed = true;
        try {
          writeFileSync(
            errorPath,
            `${JSON.stringify({
              at: now().toISOString(),
              error: error instanceof Error ? error.message : String(error),
            })}\n`,
            "utf8",
          );
        } catch {
          // Nothing left to write to; the rule still goes on without its rows.
        }
      }
    },
  };
}

def publish_role_agent(home: Path, agent_id: str, record: dict[str, str]) -> bool:
    """Merge one agent's facts for the plugin; report whether the file changed.

    Never raises for filesystem trouble: a start the plugin cannot read about
    is simply silent, and the next start rewrites the file.
    """
    try:
        path = role_agents_path(home)
        with exclusive_file_lock(path, "Paseo role-agent facts"):
            agents = read_role_agents(home)
            publication = read_host_activity_publication(path.with_name(HOST_ACTIVITY_FILE))
            merged = dict(agents)
            if publication is not None:
                merged = {
                    key: value
                    for key, value in agents.items()
                    if key not in publication.agents
                    or publication.agents[key].state != "ended"
                    or _registration_survives_end(
                        value, publication.bootId, publication.agents[key]
                    )
                }
            registered = dict(record)
            if publication is not None:
                registered["registration"] = json.dumps(
                    [publication.bootId, datetime.now(UTC).isoformat()]
                )
            merged[agent_id] = registered
            if merged == agents:
                return False
            atomic_write_text(path, json.dumps({"agents": merged}, indent=2) + "\n")
            return True
    except OSError:
        return False
